package org.sleepwell.app;
import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import org.junit.Test;import static org.junit.Assert.*;
public class SonarRuntimeTest {
 @Test public void factoryFailureAndImmediateCancelReleaseOwnership()throws Exception{for(boolean cancel:new boolean[]{false,true}){CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);SonarRuntime runtime=new SonarRuntime((cfg,closed)->{entered.countDown();release.await();throw new IllegalStateException("injected open failure");},Runnable::run,s->{},new SonarPumpTest.Clock());assertTrue(runtime.start(SonarConfig.defaults()));assertTrue(entered.await(2,TimeUnit.SECONDS));if(cancel)runtime.cancel();release.countDown();assertTrue(runtime.awaitClosed(3000));assertFalse(runtime.state().busy);assertFalse(runtime.state().ready);assertEquals(cancel?"CANCELLED":"ERROR",runtime.state().phase);}}
 @Test public void blockedCloseRetainsProcessLeaseUntilActualWorkerCleanup()throws Exception{CountDownLatch closing=new CountDownLatch(1),release=new CountDownLatch(1);SonarPumpTest.Io io=new SonarPumpTest.Io(){public void close(){closing.countDown();boolean interrupted=false;for(;;)try{release.await();break;}catch(InterruptedException e){interrupted=true;}super.close();if(interrupted)Thread.currentThread().interrupt();}};io.failure=SonarFrame.Quality.SILENCED;io.failAt=1;SonarRuntime first=new SonarRuntime((c,x)->io,Runnable::run,s->{},new SonarPumpTest.Clock());assertTrue(first.start(SonarConfig.defaults()));assertTrue(closing.await(2,TimeUnit.SECONDS));first.cancel();assertTrue(first.state().busy);assertFalse(first.awaitClosed(30));AtomicInteger opens=new AtomicInteger();SonarRuntime rejected=new SonarRuntime((c,x)->{opens.incrementAndGet();return new SonarPumpTest.Io();},Runnable::run,s->{},new SonarPumpTest.Clock());assertFalse(rejected.start(SonarConfig.defaults()));assertEquals(0,opens.get());release.countDown();assertTrue(first.awaitClosed(3000));SonarRuntime after=new SonarRuntime((c,x)->{throw new IllegalStateException("proof reopened lease");},Runnable::run,s->{},new SonarPumpTest.Clock());assertTrue(after.start(SonarConfig.defaults()));assertTrue(after.awaitClosed(3000));assertEquals("ERROR",after.state().phase);}
 @Test public void actualDspReadinessUsesRealFramesAndBoundedHistory()throws Exception{List<SonarRuntime.State> states=new CopyOnWriteArrayList<>();SonarRuntime runtime=new SonarRuntime((c,x)->new SonarPumpTest.Io(),Runnable::run,states::add,new SonarPumpTest.Clock());assertTrue(runtime.start(SonarConfig.defaults()));assertTrue(runtime.awaitClosed(6000));assertTrue(runtime.state().ready);assertEquals("DONE",runtime.state().phase);assertTrue(runtime.snapshot().size()<=375);assertTrue(runtime.snapshot().stream().anyMatch(f->f.movement!=null));assertTrue(states.size()<=103);assertFalse(runtime.start(SonarConfig.defaults()));}
 @Test public void uncertainCloseRefusesAnotherAllocationUntilProcessRestart()throws Exception{java.lang.reflect.Field field=SonarRuntime.class.getDeclaredField("OWNER");field.setAccessible(true);@SuppressWarnings("unchecked") AtomicReference<Object> lease=(AtomicReference<Object>)field.get(null);assertNull(lease.get());try{SonarPumpTest.Io io=new SonarPumpTest.Io(){public void close(){throw new IllegalStateException("injected unconfirmed native release");}};io.failure=SonarFrame.Quality.SILENCED;io.failAt=1;SonarRuntime runtime=new SonarRuntime((c,x)->io,Runnable::run,s->{},new SonarPumpTest.Clock());assertTrue(runtime.start(SonarConfig.defaults()));assertTrue(runtime.awaitClosed(3000));assertEquals("BLOCKED",runtime.state().phase);assertNotNull(lease.get());AtomicInteger opened=new AtomicInteger();SonarRuntime denied=new SonarRuntime((c,x)->{opened.incrementAndGet();return new SonarPumpTest.Io();},Runnable::run,s->{},new SonarPumpTest.Clock());assertFalse(denied.start(SonarConfig.defaults()));assertEquals(0,opened.get());}finally{lease.set(null); /* Only this test's fake IO exists. Production has no lease reset API. */}}
 @Test public void queuedTerminalCannotRestoreReadinessAfterCancel()throws Exception{java.util.Queue<Runnable> queued=new java.util.concurrent.ConcurrentLinkedQueue<>();List<SonarRuntime.State> delivered=new ArrayList<>();SonarRuntime runtime=new SonarRuntime((c,x)->new SonarPumpTest.Io(),queued::add,delivered::add,new SonarPumpTest.Clock());assertTrue(runtime.start(SonarConfig.defaults()));assertTrue(runtime.awaitClosed(6000));assertTrue(runtime.ready());runtime.cancel();for(Runnable next;(next=queued.poll())!=null;)next.run();assertFalse(runtime.ready());assertFalse(runtime.state().ready);assertTrue(delivered.stream().noneMatch(s->s.ready));}
}
